// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount, address user) public {
        vm.assume(user != address(0));
        vm.assume(amount > 0);
        vm.deal(user, amount);
        vm.prank(user);
        c.addToBalance{value: amount}();
        uint256 bal = c.getBalance(user);
        assertTrue(bal == amount, "getBalance must return deposited amount");
    }
}
